class Solution {
    public String[] findOcurrences(String text,String first,String second){
        String[] words=text.split(" ");
        List<String> answer=new ArrayList<>();
        for(int i=0;i+2<words.length;i++)if(words[i].equals(first)&&words[i+1].equals(second))answer.add(words[i+2]);
        return answer.toArray(new String[0]);
    }
}

code.kotlin:
class Solution {
    fun findOcurrences(text:String,first:String,second:String):Array<String>{
        val words=text.split(" ");
        val answer=mutableListOf<String>();
        for(i in 0 until words.size-2)if(words[i]==first&&words[i+1]==second)answer.add(words[i+2]);
        return answer.toTypedArray()
    }
}

code.cpp:
class Solution {
    public: vector<string> findOcurrences(string text,string first,string second){
        istringstream input(text);
        vector<string> words,answer;
        for(string word;input>>word;)words.push_back(word);
        for(int i=0;i+2<(int)words.size();++i)if(words[i]==first&&words[i+1]==second)answer.push_back(words[i+2]);
        return answer;
    }
};
